//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_pf.js");
scwin.vScrenID = "ULDSTF09340.xml";
scwin.fr_MktId = $c.lcp.fn_getMktId();
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Isu_cd = "", scwin.Isu_nm = "", scwin.fr_bz_procs_no = "", scwin.select_gubun = "3", scwin.today_dd = "", scwin.cal_dd = "", scwin.fst_dtect_dd = "", scwin.inq_dd = "", scwin.design_dd = "";
scwin.fr_SecuGrpId = $c.lcp.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.showObj(cmb_RegistType, false);
    $c.stf.showObj(lbl_RegistType, false);
    //showObj(img_Regist, false);

    scwin.fn_today_dd();
    scwin.fn_cal_dd();
    MaxTab_1.setSelectedTabIndex(1);
};
scwin.fn_today_dd = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_INVSTWARN_DATE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstproc.invstwarn_today_dd.select";
    dts_Cand.DataID = encodeURI(url);
    dts_Cand.reset();
    scwin.today_dd = dts_Cand.getCellData(1, "TODAY_DD");
    $c.stf.setObjectValue(edt_search_date_1, scwin.today_dd);
    $c.stf.setObjectValue(edt_search_date_2, scwin.today_dd);
    $c.stf.setObjectValue(edt_search_date_3, scwin.today_dd);
    $c.stf.setObjectValue(edt_search_date_4, scwin.today_dd);
    $c.stf.setObjectValue(edt_search_date_5, scwin.today_dd);
    $c.stf.setObjectValue(edt_search_date_6, scwin.today_dd);
};
scwin.fn_cal_dd = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_INVSTWARN_DATE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstproc.invstwarn_next_dd.select" + "&{P}param01=" + $c.stf.getObjectValue(edt_search_date_1);
    dts_Cand.DataID = encodeURI(url);
    dts_Cand.reset();
    scwin.cal_dd = dts_Cand.getCellData(1, "NEXT_DD");
};
scwin.fn_invstwarn_cls = function() {
    var trd_dd = "";
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 1:
            trd_dd = $c.stf.getObjectValue(edt_search_date_1);
            break;
        case 2:
            trd_dd = $c.stf.getObjectValue(edt_search_date_2);
            break;
        case 3:
            trd_dd = $c.stf.getObjectValue(edt_search_date_3);
            break;
        case 4:
            trd_dd = $c.stf.getObjectValue(edt_search_date_4);
            break;
        case 5:
            trd_dd = $c.stf.getObjectValue(edt_search_date_5);
            break;
        case 6:
            trd_dd = $c.stf.getObjectValue(edt_search_date_6);
            break;
    }
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_INVSTWARNISU_CLS_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstproc.invstwarn_md_progm_prog.select" + "&{P}param01=" + trd_dd;
    dts_Cls.DataID = encodeURI(url);
    dts_Cls.reset();
    $c.stf.setObjectValue(txb_ClsDtl, dts_Cls.getCellData(1, "CLS_YN"));
};
scwin.fn_search = function() {
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 1:
            scwin.fn_search_1();
            break;
        case 2:
            scwin.fn_search_2();
            break;
        case 3:
            scwin.fn_search_3();
            break;
        case 4:
            scwin.fn_search_4();
            break;
        case 5:
            scwin.fn_search_5();
            break;
        case 6:
            scwin.fn_search_6();
            break;
    }
};



//최초적출 조회
scwin.fn_search_1 = function() {
    scwin.fn_invstwarn_cls();
    if ($c.stf.getObjectValue(edt_search_date_1) == "") {
        $c.win.alert("조회일자를 입력하세요.");
        edt_search_date_1.focus();
        return;
    }
    //lds.stf.lstproc.pf.invstwarn.list.select
    var url = "/pf/Invstwarn.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchPfInvstwarn" + "&DIV_IDX=" + DIV_IDX_PF_INVSTWARN + "&TRS_IDX=" + TRS_IDX_SELECT + "&TRD_DD=" + $c.stf.getObjectValue(edt_search_date_1) + "&SECUGRP_ID=" + scwin.fr_SecuGrpId + "&GUBUN_CD=01";
    dts_1.DataID = encodeURI(url);
    dts_1.reset();
    $c.cm.ShowWin(grd_1);
};

//지정예고
