//최초적출 신규
scwin.fn_new_create_frame_1 = async function() {
    await $c.frame.CreateDialogFrame("DLG_INVSTWARN", "../pf/ULDSTF09341.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자유의종목 최초적출", 200, 100, 710, 530, "window");
};

