    await $c.frame.CreateDialogFrame("DLG_INVSTWARN", "../pf/ULDSTF09342.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자유의종목 지정예고", 200, 100, 720, 550, "window");
};

