    await $c.frame.CreateDialogFrame("DLG_INVSTWARN", "../pf/ULDSTF09345.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 지정해제", 200, 100, 720, 490, "window");
};
scwin.fn_new_create_frame_6 = function() {
    if (cmb_RegistType.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistType.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNewTrdHalt;
    scwin.fn_SetPar = undefined;
    scwin.fn_new_create_frame_trdHalt(cmb_RegistType.BindColVal, "");
};
scwin.fn_new_create_frame_trdHalt = async function(arg, startDd) {
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_AGN", "../pf/ULDSTF09043_new.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정", 200, 200, 745, 540, "window");
            break;
        case "1":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../pf/ULDSTF09044_new.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제", 200, 200, 745, 650, "window");
            break;
        case "2":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../pf/ULDSTF09042_new.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제", 200, 200, 745, 570, "window");
            break;
    }
    cmb_RegistType.setSelectedIndex(0);
};
scwin.fn_update_create_frame_trdHalt = async function(arg, startDd) {
    if (arg == "1" && startDd != "") arg = "3";

    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_AGN", "../pf/ULDSTF09043.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정", 200, 200, 745, 540, "window");
            break;
        case "1":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../pf/ULDSTF09044.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제", 200, 200, 745, 650, "window");
            break;
        case "2":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../pf/ULDSTF09042.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제", 200, 200, 745, 570, "window");
            break;
        case "3":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../pf/ULDSTF09044.gfm", $c.lcp.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제", 200, 200, 745, 610, "window");
            break;
    }
    cmb_RegistType.setSelectedIndex(0);
};

//투자유의  신규 파라메터
scwin.fn_GetParNew = function(arrPar) {
    arrPar[0] = scwin.Isu_cd;
    arrPar[1] = scwin.Isu_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = ""; //fr_bz_procs_no

    arrPar[5] = scwin.design_dd;
    arrPar[6] = scwin.inq_dd;
    arrPar[7] = scwin.fst_dtect_dd;
    arrPar[8] = scwin.Isur_cd;
};


//투자유의  수정 파라메터
scwin.fn_GetParUpdate = function(arrPar) {
    arrPar[0] = scwin.Isu_cd;
    arrPar[1] = scwin.Isu_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = scwin.fr_bz_procs_no;
    arrPar[5] = scwin.design_dd;
    arrPar[6] = scwin.inq_dd;
    arrPar[7] = scwin.fst_dtect_dd;
    arrPar[8] = scwin.Isur_cd;
    return arrPar.length;
};

//매매거래정지  신규 파라메터
scwin.fn_GetParNewTrdHalt = function(arrPar) {
    // 넘길 인수를 지정하는 펑션

    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.Isur_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = "";
    arrPar[5] = cmb_RegistType.BindColVal;
    arrPar[6] = ""; // 종목코드
    arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)				

    arrPar[8] = scwin.fst_dtect_dd; //최초지정일
    arrPar[9] = scwin.design_dd; //매매거래정지일
    arrPar[10] = scwin.inq_dd; //조회일 
    arrPar[11] = "424";
    arrPar[12] = "투자유의종목(상장형 수익증권)";
    arrPar[13] = "";
    var remk = "";
    if (cmb_RegistType.BindColVal == "0") {
        //매매거래정지 정지
        remk = "상기 종목은 시장상황급변 등으로 투자자보호 및 시장안정을 위하여 매매거래가 정지됩니다.\r\n" + "매매거래정지 해제 시 별도의 시장안내가 있을 예정이며,\r\n" + "매매거래 재개시 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.";
    } else if (cmb_RegistType.BindColVal == "1") {
        //매매거래정지 해제
        remk = "상기 종목은 매매거래정지 사유가 해소됨에 따라 매매거래정지가 해제되며,\r\n" + "매매거래정지해제일부터 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.";
    } else if (cmb_RegistType.BindColVal == "2") {
        //매매거래정지 및 해제 
        remk = "상기 종목은 투자유의종목 지정단위기간(3매매거래일)이 종료하는 날에 장종료시 실시간 괴리율이\r\n" + "규정상 의무범위의 3배 이상에 해당하여 1일간 매매거래가 정지됩니다.\r\n" + "매매거래정지해제일부터는 지정단위기간이 새롭게 시작되며, 단일가 매매로 거래가 재개됩니다\r\n\r\n" + "※ 시장상황급변 등 투자자보호 및 시장안정을 위해 매매거래정지 기간은 연장될 수 있습니다.";
    }
    arrPar[14] = remk;
    arrPar[15] = scwin.Isu_cd;
    arrPar[16] = scwin.Isu_nm;
    return arrPar.length;
};

//매매거래정지  수정 파라메터
scwin.fn_GetParUpdateTrdHalt = function(arrPar) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.Isur_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = scwin.fr_bz_procs_no;
    arrPar[5] = dts_6.getCellData(dts_6.getRowPosition(), "HALT_DESNRELS_TP_CD");
    arrPar[6] = "";
    arrPar[7] = "";
    arrPar[8] = scwin.fst_dtect_dd; //최초지정일
    arrPar[9] = scwin.design_dd; //매매거래정지일
    arrPar[10] = scwin.inq_dd; //조회일 

    arrPar[15] = scwin.Isu_cd;
    arrPar[16] = scwin.Isu_nm;
};
scwin.fn_GetParRelease = function(arrPar) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.Isur_nm;
    arrPar[2] = scwin.fr_SecuGrpId;
    arrPar[3] = scwin.fr_MktId;
    arrPar[4] = scwin.fr_bz_procs_no;
    arrPar[5] = "1";
    arrPar[6] = ""; // 발행사/기초자산 구분값
    arrPar[7] = ""; // 발행사/기초자산 구분값

    arrPar[8] = scwin.fst_dtect_dd; //최초지정일
    arrPar[9] = scwin.design_dd; //매매거래정지일
    arrPar[10] = scwin.inq_dd; //조회일 
    arrPar[11] = "상기 종목은 매매거래정지 사유가 해소됨에 따라 매매거래정지가 해제되며,\r\n" + "매매거래정지해제일부터 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.";
    arrPar[12] = "new";
};
