scwin.grd_6_OnDblClick = function(row, colid) {
    scwin.fr_bz_procs_no = dts_6.getCellData(row, "BZ_PROCS_NO");
    scwin.Isu_cd = dts_6.getCellData(row, "ISU_CD");
    scwin.Isu_nm = dts_6.getCellData(row, "ISU_NM");
    scwin.Isur_cd = dts_6.getCellData(row, "ISUR_CD");
    scwin.Isur_nm = dts_6.getCellData(row, "ISUR_NM");
    scwin.fst_dtect_dd = dts_6.getCellData(row, "FST_DTEC_DD");
    scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_6);
    scwin.design_dd = scwin.cal_dd;
    if (scwin.fr_bz_procs_no == "" && dts_6.getCellData(row, "HALT_DESNRELS_TP_CD") == "1") {
        //종목해제인경우
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_TRD_SUSP_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.pf.invstwarn.halt_desnrels_0.select" + "&{P}param01=" + scwin.Isu_cd + "&{P}param02=" + scwin.fst_dtect_dd;
        dset_haltRealese.DataID = encodeURI(url);
        dset_haltRealese.reset();
        scwin.fr_bz_procs_no = dset_haltRealese.getCellData(1, "BZ_PROCS_NO");
        scwin.fn_GetPar = fn_GetParRelease;
        scwin.fn_SetPar = undefined;
    } else {
        scwin.fr_bz_procs_no = dts_6.getCellData(row, "BZ_PROCS_NO");
        if (scwin.fr_bz_procs_no == "") {
            scwin.fn_GetPar = fn_GetParNewTrdHalt;
            scwin.fn_SetPar = undefined;
        } else {
            scwin.fn_GetPar = fn_GetParUpdateTrdHalt; //매매거래정지
            scwin.fn_SetPar = undefined;
        }
    }
    if (scwin.fr_bz_procs_no != "") {
        scwin.fn_update_create_frame_trdHalt(dts_6.getCellData(row, "HALT_DESNRELS_TP_CD"), dts_6.getCellData(row, "TRD_HALT_STRT_DD"));
    } else {
        if (dts_6.getCellData(row, "HALT_DESNRELS_TP_CD") == '0') {
            //정지
            if (cmb_RegistType.BindColVal != '0') {
                //정지 
                cmb_RegistType.BindColVal = "2"; //지정 및 해제 

            }
            scwin.fn_new_create_frame_trdHalt(cmb_RegistType.BindColVal, "");
        } else {
            cmb_RegistType.BindColVal = dts_6.getCellData(row, "HALT_DESNRELS_TP_CD");
            scwin.fn_new_create_frame_trdHalt(dts_6.getCellData(row, "HALT_DESNRELS_TP_CD"), "");
        }
    }
};
scwin.MaxTab_1_OnSelChanged = function(nIndex) {
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 1:
        case 2:
            $c.stf.showObj(img_Regist, false);
            break;
        case 3:
        case 4:
        case 5:
        case 6:
            $c.stf.showObj(img_Regist, true);
            break;
    }
    if (MaxTab_1.getSelectedTabIndex() == 6) {
        $c.stf.showObj(cmb_RegistType, true);
        $c.stf.showObj(lbl_RegistType, true);
    } else {
        $c.stf.showObj(cmb_RegistType, false);
        $c.stf.showObj(lbl_RegistType, false);
    }
    scwin.fn_search();
};
