scwin.img_Regist_onclick = function() {
    scwin.Isu_cd = "";
    scwin.Isu_nm = "";
    scwin.Isur_cd = "";
    scwin.Isur_nm = "";
    scwin.fst_dtect_dd = "";
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 1:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_1);
            scwin.design_dd = scwin.inq_dd;
            break;
        case 2:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_2);
            scwin.design_dd = scwin.cal_dd;
            break;
        case 3:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_3);
            scwin.design_dd = scwin.cal_dd;
            break;
        case 4:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_4);
            scwin.design_dd = scwin.cal_dd;
            break;
        case 5:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_5);
            scwin.design_dd = scwin.cal_dd;
            break;
        case 6:
            scwin.inq_dd = $c.stf.getObjectValue(edt_search_date_6);
            scwin.design_dd = scwin.cal_dd;
            break;
    }
    if (scwin.inq_dd < scwin.today_dd) {
        $c.win.alert("과거 조회일자인 경우 조회만 가능합니다.");
        return;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    switch (MaxTab_1.getSelectedTabIndex()) {
        case 1:
            scwin.fn_new_create_frame_1();
            break;
        case 2:
            scwin.fn_new_create_frame_2();
            break;
        case 3:
            scwin.fn_new_create_frame_3();
            break;
        case 4:
            scwin.fn_new_create_frame_4();
            break;
        case 5:
            scwin.fn_new_create_frame_5();
            break;
        case 6:
            scwin.fn_new_create_frame_6();
            break;
    }
};
